INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "资治通鉴·卷259", "source_type": "primary", "author": "司马光等", "edition": "仓库电子文本；未核纸本。疑似转录讹字保留并单独注明。", "url": "https://github.com/greed-216/histree/blob/17a0b9a305d40d6371bbdd66d1827c8f2f7321fa/resources/derived/tongjian/259.txt", "note": "卷259景福二年条；书、卷、年、段落及行号见批次账本。", "id": "11259805-3f07-5bc8-abc5-ffdc4ecb7b11"}, {"title": "新五代史·卷43·李彦威传·身份摘录", "source_type": "primary", "author": "欧阳修", "edition": "仓库PDF派生电子文本；逐字及换行保留，未核纸本。", "url": "https://github.com/greed-216/histree/blob/17a0b9a305d40d6371bbdd66d1827c8f2f7321fa/resources/derived/twenty-four-histories/19%E6%96%B0%E4%BA%94%E4%BB%A3%E5%8F%B2.jsonl#L797", "note": "原PDF第797页，只补当前主线段落。", "id": "8a1c002e-1319-5ecd-9d86-be821f38d71c"}, {"title": "旧五代史·卷1·梁太祖纪·彭门段", "source_type": "primary", "author": "薛居正等", "edition": "仓库PDF派生电子文本；逐字及换行保留，未核纸本。", "url": "https://github.com/greed-216/histree/blob/17a0b9a305d40d6371bbdd66d1827c8f2f7321fa/resources/derived/twenty-four-histories/18%E6%97%A7%E4%BA%94%E4%BB%A3%E5%8F%B2.jsonl#L24", "note": "原PDF第24页，只补当前主线段落。", "id": "317374d0-5318-5bc1-a16b-b570e7217c37"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱友裕", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：朱友裕。", "biography": null, "status": "draft", "id": "fd61394b-01c5-5bba-9d50-af1029c306bc"}, {"name": "时溥", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的时溥：求援者。", "biography": null, "status": "draft", "id": "075f8bab-c2fc-5a9e-b8b2-a0d12c7ac981"}, {"name": "朱瑾", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：朱瑾。", "biography": null, "status": "draft", "id": "e4226d41-278e-53c7-9e01-7e3572231e8e"}, {"name": "朱友恭", "aliases": ["李彦威", "硃友恭"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：朱友恭。", "biography": null, "status": "draft", "id": "3cf1cc65-22b1-57da-951d-b72c2d25f10f"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "庞师古", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的庞师古，在此段中为击退者。", "biography": null, "status": "draft", "id": "c4c8f403-d8b1-5c64-973d-1fe7b20adcf3"}, {"name": "朱全昱", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“朱温在即位前更名晃”中为质问者。", "biography": null, "status": "draft", "id": "4a9e8e14-490e-5b74-945b-47e8c5c92bb5"}, {"name": "张氏（朱温妻）", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：张氏（朱温妻）。", "biography": null, "status": "draft", "id": "c4f21a32-768e-5e1d-9fd8-0298ff94cb91"}, {"name": "李匡威", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：李匡威。", "biography": null, "status": "draft", "id": "bdc4b069-347f-5d1c-bafc-bbc5e7e2be44"}, {"name": "李匡筹", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：李匡筹。", "biography": null, "status": "draft", "id": "279717fd-44f2-5b26-a549-6d7701dc5746"}, {"name": "王镕", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁加授王镕、罗绍威、王处直官衔”中为受授者。", "biography": null, "status": "draft", "id": "a3d42aab-7a1f-51f4-84bc-35192b430637"}, {"name": "李抱真（李匡威判官）", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：李抱真（李匡威判官）。", "biography": null, "status": "draft", "id": "52fd287b-4cc3-5cbd-8f84-8512c0656922"}, {"name": "柳玭", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：柳玭。", "biography": null, "status": "draft", "id": "5887c4ed-629c-5741-ae3e-bcfd8c2fac60"}, {"name": "王建", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“蜀王与晋王讨论讨梁及称帝”中为致书提议者。", "biography": null, "status": "draft", "id": "b02193d6-1c17-5154-bb7c-3295ed8dbbec"}, {"name": "陈敬瑄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的陈敬瑄：此前许诺以东川酬赏高仁厚。", "biography": null, "status": "draft", "id": "ad1f9c74-f6fd-50ff-b6c3-679c0c591a71"}, {"name": "田令孜", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的田令孜：担忧杨师立作乱。", "biography": null, "status": "draft", "id": "5080b636-4944-5887-afed-2195aeb4a567"}, {"name": "冯涓", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“王建称帝，建立前蜀”中为献议者。", "biography": null, "status": "draft", "id": "44755f47-d581-512a-b824-2eeb1266ce03"}, {"name": "张涛", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：张涛。", "biography": null, "status": "draft", "id": "57b1d308-7d30-5b7f-ab4a-bd97811b2e6a"}, {"name": "敬翔", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“敬翔主持崇政院，枢密院职事并入”中为受命者。", "biography": null, "status": "draft", "id": "2d3c796e-c064-52f4-90c8-1524b6b9f0c5"}, {"name": "张延范", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：张延范。", "biography": null, "status": "draft", "id": "6e86081b-ff5d-5258-a8a0-f846aae2ce26"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱友恭谮朱友裕，朱全忠命庞师古代将", "start_year": 893, "end_year": 893, "time_original": "893年二月条；具体日未载", "dynasty": "唐", "description": "朱友裕围彭城，时溥多次出兵，友裕闭壁不战；朱瑾夜逃，友裕没有追击。都虞候朱友恭写信向朱全忠谮友裕，朱全忠发怒，驿书命庞师古替代领军并调查。", "phases": [], "location_name": "彭城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3f3bf599-5645-5dc5-ac06-3db8987cfedb"}, {"title": "误收父亲驿书，朱友裕逃砀山藏伯父处", "start_year": 893, "end_year": 893, "time_original": "误得驿书后；具体日未载", "dynasty": "唐", "description": "本送庞师古的驿书误到朱友裕处，友裕害怕，率二千骑逃入山中，再潜到砀山藏在伯父朱全昱家。", "phases": [], "location_name": "山中、砀山", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "10255e02-6d6a-5118-875b-3dad811000a1"}, {"title": "张夫人使朱友裕归汴，抱救免死", "start_year": 893, "end_year": 893, "time_original": "朱友裕潜砀山之后；具体日未载", "dynasty": "唐", "description": "张夫人听闻后使朱友裕单骑去汴州见朱全忠。友裕伏地哭拜，朱全忠命左右抓按将杀他；张夫人赶来抱住，哭称其弃兵束身归罪足见无异志。朱全忠醒悟放过他，使其权知许州。", "phases": [], "location_name": "砀山、汴州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "40b26701-ee6e-5f62-a847-f96a803119ee"}, {"title": "朱友恭原名李彦威，幼为家僮后被收养", "start_year": null, "end_year": null, "time_original": "幼时；确切年日未载", "dynasty": "唐", "description": "《通鉴》记朱友恭是寿春人李彦威，幼年为朱全忠家僮，被朱全忠养为子。", "phases": [], "location_name": "寿春（籍贯）", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b7983f21-1851-51af-924e-ca405222a20d"}, {"title": "张夫人遣使召返出征的朱全忠之总述", "start_year": null, "end_year": null, "time_original": "或将兵出中途；各次确年未载", "dynasty": "唐", "description": "《通鉴》述朱全忠有时领兵出发，张夫人认为不可，派一人召回，朱全忠立即返回。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "57ba058a-405c-5a27-9f45-df6e5d66d84c"}, {"title": "庞师古攻拔佛山寨，徐兵不再出", "start_year": 893, "end_year": 893, "time_original": "893年二月条；具体日未载", "dynasty": "唐", "description": "庞师古攻佛山寨，攻下后徐州军不再敢出战。", "phases": [], "location_name": "佛山寨、徐州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4f942ec6-dc8b-54c8-b40d-aa2b45c7786b"}, {"title": "李匡威出援前酒醉侵害弟妻", "start_year": 893, "end_year": 893, "time_original": "将发幽州救王镕时；具体日未载", "dynasty": "唐", "description": "李匡威将从幽州出发援救王镕，家人聚会送别；他酒醉侵害其弟李匡筹的妻子。", "phases": [], "location_name": "幽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0f85af2c-651b-5e47-a0ab-60ee8ccac2c3"}, {"title": "李匡筹据军府自称留后、召还行营兵", "start_year": 893, "end_year": 893, "time_original": "893年二月；匡威自镇州还至博野时", "dynasty": "唐", "description": "李匡威从镇州返回至博野时，李匡筹占军府自称留后，用符召还行营兵。李匡威部众散归，只同亲近者留深州，无处进退。", "phases": [], "location_name": "幽州、博野、深州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6ddbaed3-c35b-5ecd-b589-13574a6a2bfb"}, {"title": "李匡威遣判官李抱真请归京师，引坊市恐慌", "start_year": 893, "end_year": 893, "time_original": "失军府后；具体日未载", "dynasty": "唐", "description": "李匡威派判官李抱真上奏请归京师。京师经历多次大乱，听说他要来，坊市恐慌，称金头王来图社稷，部分士民逃入山谷。", "phases": [], "location_name": "深州、京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "688e0449-e166-5aba-b890-7c8173fac556"}, {"title": "王镕迎李匡威镇州筑第，父礼相待", "start_year": 893, "end_year": 893, "time_original": "李匡威请归京后条；具体日未载", "dynasty": "唐", "description": "王镕感念李匡威因援救自己而失地，迎他到镇州，筑住宅，以父亲之礼对待。", "phases": [], "location_name": "镇州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "992c971e-b70d-5da5-af55-f714dfb1e445"}, {"title": "柳玭由渝州刺史转泸州刺史", "start_year": 893, "end_year": 893, "time_original": "893年二月条；具体日未载", "dynasty": "唐", "description": "朝廷以渝州刺史柳玭为泸州刺史。", "phases": [], "location_name": "渝州、泸州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2afb21ce-3fb1-5764-9b5a-1d7914a71e18"}, {"title": "柳玭告诫子弟门第可畏不可恃", "start_year": null, "end_year": null, "time_original": "戒其子弟时；确年未载", "dynasty": "唐", "description": "柳玭告诫子弟：门第高既要敬畏又不可倚仗；自己有失，责罚比他人重；门高易骄，族盛易招嫉，才行未获信而小失易被指摘，故应更勤学、更谨慎行事。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "e25db27d-781b-5b3e-9175-973c55531d1d"}, {"title": "王建屡请杀陈敬瑄田令孜，朝廷不许", "start_year": null, "end_year": null, "time_original": "屡请；具体起止未载", "dynasty": "唐", "description": "王建多次请杀陈敬瑄与田令孜，朝廷不批准。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "1d37195a-f466-5989-82fc-cabbeaa6f164"}, {"title": "王建使告陈敬瑄作乱，杀于新津", "start_year": 893, "end_year": 893, "time_original": "893年夏四月乙亥", "dynasty": "唐", "description": "王建派人告发陈敬瑄谋作乱，在新津将其杀死。", "phases": [], "location_name": "新津", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "004a04f0-fc82-5fc3-b76d-73aad4f90a3d"}, {"title": "王建使告田令孜通凤翔书，下狱死", "start_year": 893, "end_year": 893, "time_original": "893年四月乙亥条后；死亡具体日未载", "dynasty": "唐", "description": "王建又派人告发田令孜与凤翔通信，田令孜下狱后死亡。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "6508d4e7-ad08-5d83-9591-0d689197c675"}, {"title": "冯涓为王建草奏，辩解专杀先机", "start_year": 893, "end_year": 893, "time_original": "陈田遇害后奏报；具体日未载", "dynasty": "唐", "description": "王建命节度判官冯涓草拟奏表。奏中用开匣出虎孔子不责他人、当路斩蛇孙叔敖非为己利的典故，为军外专杀与先机制乱辩解。", "phases": [], "location_name": "西川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6744e087-fd88-5da4-9e0f-21d19511bbbe"}, {"title": "张涛称进军日不吉，敬翔劝勿懈攻", "start_year": 893, "end_year": 893, "time_original": "汴军攻徐累月时；具体日未载", "dynasty": "唐", "description": "汴军攻徐州数月未下，通事官张涛写信向朱全忠说进军日期不吉故无功，朱认为有理。敬翔指出攻城耗费已多、徐人已困，若军士听到这种说法会松懈，朱全忠便烧信。", "phases": [], "location_name": "徐州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b2d3e280-97dd-5567-aefe-1bcbb9463d82"}, {"title": "朱全忠亲自赴徐州", "start_year": 893, "end_year": 893, "time_original": "893年四月癸未", "dynasty": "唐", "description": "朱全忠亲自率军前往徐州。", "phases": [], "location_name": "徐州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1b440362-45db-5de1-a99d-8fe21bc8efe6"}, {"title": "庞师古拔彭城，时溥举族自焚", "start_year": 893, "end_year": 893, "time_original": "893年四月戊子", "dynasty": "唐", "description": "庞师古攻下彭城，时溥带全族登燕子楼自焚而死。", "phases": [], "location_name": "彭城、燕子楼", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "943e751a-cc81-5331-8221-c342f7c7289e"}, {"title": "朱全忠入彭城，张廷范知感化留后", "start_year": 893, "end_year": 893, "time_original": "893年四月己丑", "dynasty": "唐", "description": "朱全忠进入彭城，以宋州刺史张廷范知感化留后，上奏请求朝廷任文臣为节度使。", "phases": [], "location_name": "彭城、感化", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3bda2df4-fec4-5b35-8a41-61dd0f85117b"}]'::jsonb)
