SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "朱友裕围彭城，时溥多次出兵，友裕闭壁不战；朱瑾夜逃，友裕没有追击。都虞候朱友恭写信向朱全忠谮友裕，朱全忠发怒，驿书命庞师古替代领军并调查。", "citation": "卷259·景福二年（893）·zztj-v259-y0893-p008·原文件第61行", "note": "原文：硃友裕围彭城，时溥数出兵，友裕闭壁不战。硃瑾宵遁，友裕不追，都虞候硃友恭以书谮友裕于全忠。全忠怒，驿书下都指挥使庞师古，使代之将，且按其事。书误达于友裕，友裕大惧，以二千骑逃入山中，潜诣砀山，匿于伯父全昱之所。全忠夫人张氏闻之，使友裕单骑诣汴州见全忠，泣涕拜伏于庭；全忠命左右捽抑，将斩之，夫人趋就抱之，泣曰“汝舍兵众，束身归罪，无异志明矣。”全忠悟而舍之，使权知许州。友恭，寿春人李彦威也，幼为全忠家僮，全忠养以为子。张夫人，砀山人，多智略，全忠敬惮之，虽军府事，时与之谋议；或将兵出，中途，夫人以为不可，遣一介召之，全忠立为之返。；核对说明：谮是史书用词，不把指控当证实异志；闭壁不追与函令各自因果依段述，不补未载书信全文。", "status": "draft", "id": "5a74ce84-f54c-5e27-8d76-5ffb5e2d3417", "subject_id": "3f3bf599-5645-5dc5-ac06-3db8987cfedb", "source_id": "11259805-3f07-5bc8-abc5-ffdc4ecb7b11"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "893年二月条；具体日未载", "citation": "卷259·景福二年（893）·zztj-v259-y0893-p008·原文件第61行", "note": "原文：硃友裕围彭城，时溥数出兵，友裕闭壁不战。硃瑾宵遁，友裕不追，都虞候硃友恭以书谮友裕于全忠。全忠怒，驿书下都指挥使庞师古，使代之将，且按其事。书误达于友裕，友裕大惧，以二千骑逃入山中，潜诣砀山，匿于伯父全昱之所。全忠夫人张氏闻之，使友裕单骑诣汴州见全忠，泣涕拜伏于庭；全忠命左右捽抑，将斩之，夫人趋就抱之，泣曰“汝舍兵众，束身归罪，无异志明矣。”全忠悟而舍之，使权知许州。友恭，寿春人李彦威也，幼为全忠家僮，全忠养以为子。张夫人，砀山人，多智略，全忠敬惮之，虽军府事，时与之谋议；或将兵出，中途，夫人以为不可，遣一介召之，全忠立为之返。；核对说明：谮是史书用词，不把指控当证实异志；闭壁不追与函令各自因果依段述，不补未载书信全文。", "status": "draft", "id": "bf8b33a3-e5bd-500f-914c-ab1225e75276", "subject_id": "3f3bf599-5645-5dc5-ac06-3db8987cfedb", "source_id": "11259805-3f07-5bc8-abc5-ffdc4ecb7b11"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记朱友裕：围城及被谮将领。", "citation": "卷259·景福二年（893）·zztj-v259-y0893-p008·原文件第61行", "note": "原文：硃友裕围彭城，时溥数出兵，友裕闭壁不战。硃瑾宵遁，友裕不追，都虞候硃友恭以书谮友裕于全忠。全忠怒，驿书下都指挥使庞师古，使代之将，且按其事。书误达于友裕，友裕大惧，以二千骑逃入山中，潜诣砀山，匿于伯父全昱之所。全忠夫人张氏闻之，使友裕单骑诣汴州见全忠，泣涕拜伏于庭；全忠命左右捽抑，将斩之，夫人趋就抱之，泣曰“汝舍兵众，束身归罪，无异志明矣。”全忠悟而舍之，使权知许州。友恭，寿春人李彦威也，幼为全忠家僮，全忠养以为子。张夫人，砀山人，多智略，全忠敬惮之，虽军府事，时与之谋议；或将兵出，中途，夫人以为不可，遣一介召之，全忠立为之返。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "911